WITH matched_keys AS (SELECT status FROM payments EXCEPT SELECT status FROM payments WHERE order_id IN (2, 21)), reconciled AS (SELECT s.* FROM payments s JOIN matched_keys k ON s.status = k.status) SELECT DATE_TRUNC('YEAR', paid_at) AS year_start, method, MAX(paid_at) AS last_paid_at, COUNT(DISTINCT status) AS distinct_status, ROUND(AVG(amount), 2) AS avg_amount, COUNT(*) FILTER (WHERE status = 'REFUNDED') AS refunded_rows FROM reconciled GROUP BY year_start, method
